from pathlib import Path

p = Path('annual-revision-stage.html')
s = p.read_text(encoding='utf-8')

start = s.find('function score(arr,id){')
if start < 0:
    raise SystemExit('Could not locate score()')
end = s.find('function lockScreen(){', start)
if end < 0:
    raise SystemExit('Could not locate lockScreen()')

fn = r'''function questionForBox(arr,box,i){const id=String(box.dataset.questionId||'');if(id){const exact=arr.find(q=>String(q?.id||'')===id);if(exact)return exact}const input=box.querySelector('input[name]');const name=String(input?.name||'');const m=name.match(/(?:^|[-_])([DPF]\d+)$/);const questionId=m?m[1]:'';if(questionId){const exact=arr.find(q=>String(q?.id||'')===questionId);if(exact)return exact}return {};}
function explainQuestion(q){if(q?.explanation||q?.reason||q?.feedback||q?.why)return q.explanation||q.reason||q.feedback||q.why;const text=String(q?.q||q?.question||'').trim(),opts=Array.isArray(q?.options)?q.options:[],answer=opts[q?.answer]??q?.answer,a=String(answer??'').trim();const subject=(text.match(/^(Je|Tu|Il|Elle|On|Nous|Vous|Ils|Elles)\b/i)||[])[1];const etre={Je:'suis',Tu:'es',Il:'est',Elle:'est',On:'est',Nous:'sommes',Vous:'êtes',Ils:'sont',Elles:'sont'};const avoir={Je:'ai',Tu:'as',Il:'a',Elle:'a',On:'a',Nous:'avons',Vous:'avez',Ils:'ont',Elles:'ont'};const aller={Je:'vais',Tu:'vas',Il:'va',Elle:'va',On:'va',Nous:'allons',Vous:'allez',Ils:'vont',Elles:'vont'};const vivre={Je:'vis',Tu:'vis',Il:'vit',Elle:'vit',On:'vit',Nous:'vivons',Vous:'vivez',Ils:'vivent',Elles:'vivent'};if(subject&&etre[subject]===a)return 'الضمير «'+subject+'» هو الفاعل في السؤال، وتصريف الفعل être معه هو «'+a+'»، لذلك نستخدم «'+a+'».';if(subject&&avoir[subject]===a)return 'الضمير «'+subject+'» هو الفاعل في السؤال، وتصريف الفعل avoir معه هو «'+a+'»، لذلك نستخدم «'+a+'».';if(subject&&aller[subject]===a)return 'الضمير «'+subject+'» هو الفاعل في السؤال، والفعل aller يُصرَّف معه إلى «'+a+'»؛ لذلك «'+a+'» هي الإجابة الصحيحة.';if(subject&&vivre[subject]===a)return 'الضمير «'+subject+'» هو الفاعل في السؤال، والفعل vivre يُصرَّف معه إلى «'+a+'»؛ لذلك «'+a+'» هي الإجابة الصحيحة.';if(/\bElle\s+est\s+___|\bElle\s+est\s*$/i.test(text)&&/^[a-zà-ÿ]+$/i.test(a)){return 'الفاعل «Elle» مؤنث مفرد، لذلك يجب أن تتوافق الصفة أو الجنسية معه في المؤنث المفرد. «'+a+'» هي الصيغة المؤنثة المفردة المطلوبة في السؤال.';}if(/\bIl\s+est\s+___|\bIl\s+est\s*$/i.test(text)&&/^[a-zà-ÿ]+$/i.test(a)){return 'الفاعل «Il» مذكر مفرد، لذلك يجب أن تتوافق الصفة أو الجنسية معه في المذكر المفرد. «'+a+'» هي الصيغة المذكرة المفردة المطلوبة في السؤال.';}if(/\b(Elles|Nous)\s+(sont|sommes)\s+___/i.test(text)&&/^[a-zà-ÿ]+$/i.test(a)){return 'الفاعل جمع، لذلك يجب أن تتوافق الصفة أو الجنسية معه في صيغة الجمع. «'+a+'» هي الصيغة التي توافق الفاعل الجمع.';}if(/\b(Ils|Vous)\s+(sont|êtes)\s+___/i.test(text)&&/^[a-zà-ÿ]+$/i.test(a)){return 'الفاعل مذكر جمع أو المخاطب الجمع، لذلك يجب أن تتوافق الصفة مع صيغة الجمع. «'+a+'» هي الصيغة الموافقة للفاعل.';}if(/italien|français|francais|anglais|anglaise|égyptien|egyptien|égyptienne|egyptienne|espagnol|espagnole|allemand|allemande|marocain|marocaine|tunisien|tunisienne/i.test(text+' '+a)){return 'أسماء الجنسيات صفات تتوافق مع جنس وعدد الشخص الموصوف؛ مع «Elle» نستخدم صيغة المؤنث المفرد «'+a+'»، بينما المذكر المفرد له صيغة مختلفة.';}if(['un','une','des'].includes(a)){if(/trousse|robe|jupe|chemise|veste|cravate|ceinture|gomme|pomme|carotte|maison|classe|table|chaussure|chaussette/i.test(text)&&a==='une')return 'الاسم الوارد في السؤال مؤنث مفرد، لذلك نستخدم أداة التنكير «une».';if(/livre|cahier|stylo|crayon|pantalon|pull|costume|nez|frère|père/i.test(text)&&a==='un')return 'الاسم الوارد في السؤال مذكر مفرد، لذلك نستخدم أداة التنكير «un».';if(a==='des')return 'الاسم المقصود جمع، لذلك نستخدم أداة التنكير «des».';}if(['de','d’',"d'"] .includes(a))return 'بعد النفي مع avoir تتحول أداة التنكير أو أداة الجمع إلى «de/d’»، لذلك تكون هذه هي الصيغة الصحيحة.';if(['du','de la','de l’',"de l'"] .includes(a))return 'السؤال يطلب أداة التجزئة المناسبة للاسم؛ لذلك نستخدم «'+a+'».';if(/féminin|feminin|féminine|مؤنث|femme/i.test(text))return 'السؤال يختبر صيغة المؤنث؛ لذلك نختار الصيغة المؤنثة الصحيحة «'+a+'».';if(/pluriel|جمع|elles|ils|chaussures|livres|jupes|chaussettes/i.test(text))return 'السؤال يختبر صيغة الجمع؛ لذلك يجب أن تتوافق الإجابة مع الاسم أو الفاعل الجمع في السؤال.';return 'لا يوجد تفسير صريح لهذا السؤال في بنك الأسئلة، ولم يتم العثور على قاعدة مرتبطة به.';}
function grade(arr,id,resultId){const root=$(id),out=$(resultId);let n=0,total=arr.length;root.querySelectorAll('.q').forEach(box=>{const q=questionForBox(arr,box,0),selected=box.querySelector('input:checked');if(!q.id)return;const correct=!!selected&&Number(selected.value)===Number(q.answer);box.querySelectorAll('.answer-feedback').forEach(x=>x.remove());box.querySelectorAll('.option').forEach(x=>x.classList.remove('is-correct','is-wrong'));if(selected)selected.closest('.option')?.classList.add(correct?'is-correct':'is-wrong');if(correct){n++;return}const opts=Array.isArray(q.options)?q.options:[],answer=opts[q.answer]??q.answer,reason=explainQuestion(q),div=document.createElement('div');div.className='answer-feedback';div.innerHTML='<div class="feedback-title">'+(selected?'❌ إجابتك غير صحيحة':'⚠️ لم تتم الإجابة')+'</div><div><b>✅ الإجابة الصحيحة:</b> '+esc(answer)+'</div><div><b>💡 لماذا؟</b> '+esc(reason)+'</div>';box.appendChild(div)});const pct=total?Math.round(n/total*100):0;out.innerHTML='<div class="result"><b>النتيجة: '+n+' / '+total+' ('+pct+'%)</b><br>التصحيح والتفسير مرتبطان بمعرّف السؤال نفسه.</div>';return n}
function score(arr,id){let n=0;arr.forEach((q,i)=>{const x=document.querySelector('input[name="'+id+'-'+esc(q.id||i)+'"]:checked');if(x&&Number(x.value)===Number(q.answer))n++});return n}
'''
s = s[:start] + fn + s[end:]

old_diag = "const n=score(diag,'diag');localStorage.setItem(key,JSON.stringify({version:1,target:g,score:n,total:diag.length,completedAt:new Date().toISOString()}));location.reload()"
new_diag = "const n=grade(diag,'diag','diagResult');localStorage.setItem(key,JSON.stringify({version:1,target:g,score:n,total:diag.length,completedAt:new Date().toISOString()}));$('diagBtn').disabled=true"
if old_diag in s:
    s = s.replace(old_diag, new_diag, 1)

old_practice = "$('practiceBtn').onclick=()=>{$('practiceResult').innerHTML='<div class=\"result\">النتيجة: '+score(practice,'practiceQuiz')+' / '+practice.length+'</div>'}"
new_practice = "$('practiceBtn').onclick=()=>{grade(practice,'practiceQuiz','practiceResult');$('practiceBtn').disabled=true}"
if old_practice in s:
    s = s.replace(old_practice, new_practice, 1)

old_final = "$('finalBtn').onclick=()=>{$('finalResult').innerHTML='<div class=\"result\">النتيجة: '+score(fin,'finalQuiz')+' / '+fin.length+'</div>'}"
new_final = "$('finalBtn').onclick=()=>{grade(fin,'finalQuiz','finalResult');$('finalBtn').disabled=true}"
if old_final in s:
    s = s.replace(old_final, new_final, 1)

p.write_text(s, encoding='utf-8')
print('Annual revision: rule-specific adjective/nationality explanations; no generic fallback')